using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change #1: Discriminator property renamed to "$type".
            // Preserve "Discriminator" to stay compatible with existing 500K documents
            // and direct SQL queries that reference c.Discriminator.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change #2: Id format changed from "EntityType|Key" to just the key.
            // Existing documents use "Product|123". Override id generation to keep that format.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyIdValueGenerator>();

            // EF Core 9 breaking change #3: HasIndex() now throws for Cosmos provider.
            // Cosmos indexes are managed server-side via indexing policy, not EF.
            // Removed: entity.HasIndex(p => p.Sku);
        });
    }
}

